/* Cognitive Care NER — Phase 1 secure authentication and profile onboarding. */
(()=>{
'use strict';
const PROFILE='ccner.level2.profile.v1',AUTH='ccner.level2.auth.v1',OTP='ccner.level2.pendingOtp.v1';
const CONSENT_VERSION='2026-09-05-v1';
const SUPABASE_CDN='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';
let supabase=null,currentUser=null,currentProfile=null,gateEl=null,step=0,phone='',authMode='login';
const clearLegacy=()=>{[PROFILE,AUTH,OTP,'ccner.level2.profile','ccner.level2.auth','ccner.profile','ccner-auth'].forEach(k=>{try{localStorage.removeItem(k)}catch{}})};
const app=()=>document.querySelector('.app-shell');
const ageFromDob=dob=>{const d=new Date(dob+'T00:00:00'),n=new Date();if(!dob||Number.isNaN(d.getTime())||d>n)return null;let a=n.getFullYear()-d.getFullYear();if(n.getMonth()<d.getMonth()||(n.getMonth()===d.getMonth()&&n.getDate()<d.getDate()))a--;return a>=0&&a<130?a:null};
function hideApp(){const x=app();if(x)x.style.display='none'}
function showApp(){const x=app();if(x)x.style.display=''}
function loadScript(){return new Promise((resolve,reject)=>{if(window.supabase?.createClient)return resolve();const s=document.createElement('script');s.src=SUPABASE_CDN;s.onload=()=>window.supabase?.createClient?resolve():reject(Error('Supabase SDK failed to initialize'));s.onerror=()=>reject(Error('Could not load secure authentication service'));document.head.appendChild(s)})}
function error(msg){const e=document.getElementById('l2err');if(!e)return;e.textContent=msg||'';e.classList.toggle('show',!!msg)}
function setStep(n){step=n;gateEl?.querySelectorAll('.l2-step').forEach(x=>x.classList.toggle('active',x.dataset.step==n));gateEl?.querySelectorAll('.l2-progress span').forEach((x,i)=>x.classList.toggle('active',i<(n||0)));gateEl?.querySelector('.l2-progress')?.classList.toggle('hidden',n===0);error('')}
function setMode(mode){authMode=mode;setStep(1);const title=document.getElementById('l2AuthTitle'),hint=document.getElementById('l2AuthHint'),send=document.getElementById('l2send');if(title)title.textContent=mode==='login'?'Login to your Cognitive Care account':'Create your Cognitive Care account';if(hint)hint.textContent=mode==='login'?'Enter the mobile number already registered with your account. We will send a one-time verification code.':'New to Cognitive Care? Enter your mobile number to create your account with secure OTP verification.';if(send)send.textContent=mode==='login'?'Send Login OTP':'Send Sign-up OTP'}
function renderGate(){if(gateEl)return;hideApp();gateEl=document.createElement('div');gateEl.id='l2AuthGate';gateEl.innerHTML=`<div class="l2-shell"><div class="l2-brand"><div class="puppy">🐶</div><h1>Welcome to Cognitive Care NER</h1><p>Secure access to your personal cognitive-care account.</p></div><div class="l2-card"><div class="l2-progress hidden"><span></span><span></span><span></span></div><div id="l2err" class="l2-error" role="alert"></div><section class="l2-step active" data-step="0"><div class="l2-welcome-icon">🔐</div><h2>Login or create an account</h2><p class="hint">Already registered? Login with the same mobile number. New user? Create your account once — after that, your secure session can stay signed in on this device.</p><div class="l2-actions l2-auth-choice"><button class="l2-btn primary l2-choice" id="l2login" type="button">Login</button><button class="l2-btn secondary l2-choice" id="l2signup" type="button">Sign Up</button></div><div class="l2-note"><strong>Existing users:</strong> you do not need to create a new ID again. Use Login with your registered mobile number. Reports and your protected profile remain linked to the same account.</div></section><section class="l2-step" data-step="1"><h2 id="l2AuthTitle">Login to your Cognitive Care account</h2><p class="hint" id="l2AuthHint">Enter the mobile number already registered with your account. We will send a one-time verification code.</p><div class="l2-field"><label for="l2phone">Mobile number</label><input id="l2phone" type="tel" inputmode="numeric" autocomplete="tel" placeholder="10-digit mobile number" maxlength="10"></div><div class="l2-actions"><button class="l2-btn primary" id="l2send" type="button">Send Login OTP</button><button class="l2-btn ghost" id="l2chooseBack" type="button">Back</button></div><div class="l2-note">Login never creates a new account. Sign Up is the separate path for first-time users. OTP is issued and verified by Supabase Auth.</div></section><section class="l2-step" data-step="2"><h2>Verify your mobile number</h2><p class="hint">Enter the one-time code sent to <span id="l2phoneShow" class="l2-phone"></span>.</p><div class="l2-field"><label for="l2otp">6-digit OTP</label><input id="l2otp" class="l2-otp" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="000000"></div><div class="l2-actions"><button class="l2-btn primary" id="l2verify" type="button">Verify & continue</button><button class="l2-btn ghost" id="l2back" type="button">Change number</button></div><div class="l2-note">The verification code is never stored by this app.</div></section><section class="l2-step" data-step="3"><h2>Complete your secure profile</h2><p class="hint">Required details stay in your protected profile record. Optional details can be skipped.</p><div class="l2-grid"><div class="l2-field"><label for="l2name">Full name</label><input id="l2name" autocomplete="name" placeholder="Full name" required></div><div class="l2-field"><label for="l2dob">Date of birth</label><input id="l2dob" type="date" autocomplete="bday" required></div><div class="l2-field"><label for="l2age">Age</label><input id="l2age" readonly placeholder="Calculated automatically"></div><div class="l2-field"><label for="l2gender">Gender</label><select id="l2gender"><option value="">Prefer not to say</option><option>Female</option><option>Male</option><option>Other</option><option>Prefer not to say</option></select></div><div class="l2-field"><label for="l2role">Account role</label><select id="l2role"><option value="patient">Patient</option><option value="caregiver">Caregiver</option><option value="health_worker">Doctor / Health Worker (request)</option></select><small class="l2-help">Health-worker access is recorded as a request; elevated access is not granted by the browser.</small></div><div class="l2-field"><label for="l2lang">Preferred language</label><select id="l2lang"><option value="en">English</option><option value="hi">Hindi</option><option value="bn">Bengali</option><option value="as">Assamese</option></select></div></div><div class="l2-optional"><h3>Optional information</h3><div class="l2-grid"><div class="l2-field"><label for="l2photo">Profile photo</label><input id="l2photo" type="file" accept="image/jpeg,image/png,image/webp"><small class="l2-help">Private storage · max 1 MB</small></div><div class="l2-field"><label for="l2emergency">Emergency contact</label><input id="l2emergency" type="tel" inputmode="numeric" placeholder="Mobile number" maxlength="10"></div><div class="l2-field"><label for="l2relationship">Relationship</label><input id="l2relationship" placeholder="Daughter, son, spouse…"></div><div class="l2-field"><label for="l2momoname">Momo name</label><input id="l2momoname" placeholder="Momo"></div><div class="l2-field"><label for="l2voice">Voice preference</label><select id="l2voice"><option value="default">Default</option><option value="slow">Slower</option><option value="loud">Louder</option></select></div><div class="l2-field"><label for="l2region">Region</label><input id="l2region" placeholder="State / district / NER region"></div><div class="l2-field full"><label for="l2access">Accessibility preference</label><input id="l2access" placeholder="Large text, high contrast, etc."></div></div></div><div class="l2-consent"><label><input id="l2coreConsent" type="checkbox"> <span>I agree to the app's core privacy and data-use notice so my account, profile, reminders and training data can be stored securely for this service. <strong>Required.</strong></span></label><label><input id="l2analyticsConsent" type="checkbox"> <span>Allow optional product analytics to improve usability. This can be changed later.</span></label></div><div class="l2-actions"><button class="l2-btn primary" id="l2save" type="button">Save securely & enter app</button></div><div class="l2-note">You can sign out at any time. Signing out clears the active session from this device; your protected cloud profile remains until you request deletion.</div></section></div></div>`;document.body.prepend(gateEl);wireGate()}
function wireGate(){const q=s=>gateEl.querySelector(s);q('#l2login').onclick=()=>setMode('login');q('#l2signup').onclick=()=>setMode('signup');q('#l2chooseBack').onclick=()=>setStep(0);q('#l2phone').oninput=e=>{e.target.value=e.target.value.replace(/\D/g,'').slice(0,10)};q('#l2send').onclick=sendOtp;q('#l2back').onclick=()=>setStep(1);q('#l2verify').onclick=verifyOtp;q('#l2dob').onchange=e=>q('#l2age').value=ageFromDob(e.target.value)||'';q('#l2save').onclick=saveProfile}
async function sendOtp(){error('');phone=document.getElementById('l2phone').value.replace(/\D/g,'');if(!/^[6-9]\d{9}$/.test(phone))return error('Please enter a valid 10-digit Indian mobile number.');try{const {error:e}=await supabase.auth.signInWithOtp({phone:'+91'+phone,options:{shouldCreateUser:authMode==='signup'}});if(e)throw e;document.getElementById('l2phoneShow').textContent='+91 '+phone;setStep(2);document.getElementById('l2otp')?.focus()}catch(e){const msg=e?.message||'We could not send the OTP. Please try again.';if(authMode==='login'&&/not found|sign.?up|user/i.test(msg))return error('No account was found for this mobile number. If you are a new user, go back and choose Sign Up.');error(msg)}}
async function verifyOtp(){const token=document.getElementById('l2otp').value.trim();if(!/^\d{6}$/.test(token))return error('Enter the 6-digit OTP.');try{const {data,error:e}=await supabase.auth.verifyOtp({phone:'+91'+phone,token,type:'sms'});if(e)throw e;if(!data?.user)throw Error('Verification completed but no authenticated user was returned.');currentUser=data.user;await loadProfile();if(currentProfile?.profile_complete){finishAuth(currentProfile)}else{setStep(3);prefillProfile()}}catch(e){error(e?.message||'The OTP could not be verified. Please request a new code and try again.')}}
async function loadProfile(){if(!currentUser)return null;const {data,error:e}=await supabase.from('profiles').select('*').eq('user_id',currentUser.id).maybeSingle();if(e)throw e;currentProfile=data||null;return data}
function profilePayload(){const q=s=>document.getElementById(s),dob=q('l2dob').value,requested=q('l2role').value;return {user_id:currentUser.id,full_name:q('l2name').value.trim(),display_name:q('l2name').value.trim(),date_of_birth:dob,gender:q('l2gender').value||null,requested_role:requested,role:requested==='health_worker'?'patient':requested,preferred_language:q('l2lang').value,emergency_contact:q('l2emergency').value.trim()||null,emergency_relationship:q('l2relationship').value.trim()||null,momo_name:q('l2momoname').value.trim()||'Momo',voice_preference:q('l2voice').value,region:q('l2region').value.trim()||null,accessibility:q('l2access').value.trim()||null,profile_complete:true}}
async function uploadPhoto(file){if(!file)return null;if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>1024*1024)throw Error('Profile photo must be JPG, PNG or WebP and 1 MB or smaller.');const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg',path=currentUser.id+'/avatar.'+ext;const {error:e}=await supabase.storage.from('profile-photos').upload(path,file,{upsert:true,contentType:file.type,cacheControl:'3600'});if(e)throw e;return path}
async function acceptConsent(purpose,metadata={}){const {error:e}=await supabase.from('privacy_consents').upsert({user_id:currentUser.id,consent_version:CONSENT_VERSION,purpose,metadata},{onConflict:'user_id,consent_version,purpose'});if(e)throw e}
async function audit(action,entityType='auth',entityId=null,metadata={}){try{await supabase.from('audit_log').insert({user_id:currentUser.id,action,entity_type:entityType,entity_id:entityId,metadata:{...metadata,app:'ccner',version:CONSENT_VERSION}})}catch{}}
async function saveProfile(){error('');if(!currentUser)return error('Your session expired. Please login again.');const p=profilePayload();if(!p.full_name)return error('Please enter the full name.');if(!p.date_of_birth||ageFromDob(p.date_of_birth)===null)return error('Please enter a valid date of birth.');if(!document.getElementById('l2coreConsent').checked)return error('Please accept the required privacy notice to continue.');if(p.emergency_contact&&!/^[6-9]\d{9}$/.test(p.emergency_contact))return error('Please enter a valid 10-digit emergency contact number.');const file=document.getElementById('l2photo').files[0];try{if(file)p.avatar_path=await uploadPhoto(file);const {data,error:e}=await supabase.from('profiles').upsert(p,{onConflict:'user_id'}).select('*').single();if(e)throw e;currentProfile=data;await acceptConsent('core_app',{language:p.preferred_language});if(document.getElementById('l2analyticsConsent').checked)await acceptConsent('analytics',{language:p.preferred_language});await audit('profile_completed','profile',currentUser.id,{requested_role:p.requested_role,role:p.role});finishAuth(data)}catch(e){error(e?.message||'We could not securely save your profile. Nothing has been saved locally.')}}
function finishAuth(profile){currentProfile=profile;clearLegacy();gateEl?.remove();gateEl=null;showApp();window.CCNERAuth?.__set?.(currentUser,currentProfile);window.dispatchEvent(new CustomEvent('ccner:profile-ready',{detail:{...currentProfile,userId:currentUser?.id}}))}
async function handleSession(session){if(!session?.user){currentUser=null;currentProfile=null;clearLegacy();renderGate();setStep(0);hideApp();return}try{const {data,error:e}=await supabase.auth.getUser();if(e)throw e;currentUser=data.user;await loadProfile();if(currentProfile?.profile_complete)finishAuth(currentProfile);else{renderGate();setStep(3);prefillProfile()}}catch(e){currentUser=null;currentProfile=null;renderGate();setStep(0);hideApp();error(e?.message||'Your secure session could not be validated. Please login again.')}}
function prefillProfile(){if(!currentProfile)return;const map={l2name:currentProfile.full_name||currentProfile.display_name||'',l2dob:currentProfile.date_of_birth||'',l2gender:currentProfile.gender||'',l2role:currentProfile.requested_role||currentProfile.role||'patient',l2lang:currentProfile.preferred_language||'en',l2emergency:currentProfile.emergency_contact||'',l2relationship:currentProfile.emergency_relationship||'',l2momoname:currentProfile.momo_name||'Momo',l2voice:currentProfile.voice_preference||'default',l2region:currentProfile.region||'',l2access:currentProfile.accessibility||''};Object.entries(map).forEach(([id,v])=>{const el=document.getElementById(id);if(el)el.value=v});const a=ageFromDob(map.l2dob);if(a!==null)document.getElementById('l2age').value=a}
async function boot(){hideApp();renderGate();try{await loadScript();const C=window.CCNER_CONFIG||{};if(!C.SUPABASE_URL||!C.SUPABASE_ANON_KEY)throw Error('Secure authentication is not configured for this deployment.');supabase=window.supabase.createClient(C.SUPABASE_URL,C.SUPABASE_ANON_KEY,{auth:{autoRefreshToken:true,persistSession:true,detectSessionInUrl:false}});window.CCNERAuth.__client=supabase;supabase.auth.onAuthStateChange((event,session)=>{setTimeout(()=>handleSession(session),0);if(event==='SIGNED_IN'&&session?.user){currentUser=session.user;setTimeout(()=>audit('auth_login','auth',session.user.id,{provider:'phone_otp',mode:authMode}),0)}});const {data,error:e}=await supabase.auth.getSession();if(e)throw e;await handleSession(data.session)}catch(e){error(e?.message||'Secure authentication is temporarily unavailable. Please try again.')}}
window.CCNERAuth={getProfile:()=>currentProfile,isAuthenticated:()=>!!currentUser&&!!currentProfile?.profile_complete,client:()=>supabase,signOut:async()=>{if(!supabase)return;try{await audit('auth_logout','auth',currentUser?.id||null,{provider:'phone_otp'})}finally{await supabase.auth.signOut();currentUser=null;currentProfile=null;location.reload()}},deleteLocalProfile:()=>clearLegacy(),__set:(u,p)=>{currentUser=u;currentProfile=p}};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
